   302→    const analytics: Array<{ name: string; queries: number; api: number }> = [];
   303→    
   304→    // Get last 7 days data
   305→    for (let i = 6; i >= 0; i--) {
   306→      const date = new Date();
   307→      date.setDate(date.getDate() - i);
   308→      date.setHours(0, 0, 0, 0);
   309→      
   310→      const nextDate = new Date(date);
   311→      nextDate.setDate(nextDate.getDate() + 1);
   312→      
   313→      const dayHistory = await db.select().from(schema.searchHistory)
   314→        .where(sql`${schema.searchHistory.createdAt} >= ${date} AND ${schema.searchHistory.createdAt} < ${nextDate}`);
   315→      
   316→      const dayName = dayNames[date.getDay()];
   317→      const totalQueries = dayHistory.length;
   318→      const apiQueries = dayHistory.filter(h => h.sourceType?.includes('API')).length;
   319→      
   320→      analytics.push({
   321→        name: dayName,
   322→        queries: totalQueries,
   323→        api: apiQueries,
   324→      });
   325→    }
   326→    
   327→    return analytics;
   328→  }
