    28→    fileSize: 10 * 1024 * 1024, // 10MB limit
    29→  },
    30→  fileFilter: (req, file, cb) => {
    31→    const allowedTypes = /pdf|jpeg|jpg|png/;
    32→    const extname = allowedTypes.test(path.extname(file.originalname).toLowerCase());
    33→    const mimetype = allowedTypes.test(file.mimetype);
    34→    
    35→    if (extname && mimetype) {
    36→      cb(null, true);
    37→    } else {
    38→      cb(new Error("Only PDF, JPEG, JPG, and PNG files are allowed"));
    39→    }
    40→  }
