export class DbStorage implements IStorage {
  // ─── Users ────────────────────────────────────────────────────────────────
  async getUser(id: string): Promise<User | undefined> {
    const result = await db.select().from(schema.users).where(eq(schema.users.id, id)).limit(1);
    return result[0];
  }

  async getUserByEmail(email: string): Promise<User | undefined> {
    const result = await db.select().from(schema.users).where(eq(schema.users.email, email)).limit(1);
    return result[0];
  }

  async createUser(user: InsertUser): Promise<User> {
    const hashedPassword = await bcrypt.hash(user.password, 10);
    const result = await db.insert(schema.users).values({ ...user, password: hashedPassword }).returning();
    return result[0];
  }

  async updateUser(id: string, updates: Partial<InsertUser>): Promise<User | undefined> {
    const updateData: any = { ...updates, updatedAt: new Date() };
    if (updates.password) updateData.password = await bcrypt.hash(updates.password, 10);
    const result = await db.update(schema.users).set(updateData).where(eq(schema.users.id, id)).returning();
    return result[0];
  }

  async deleteUser(id: string): Promise<void> {
    await db.delete(schema.users).where(eq(schema.users.id, id));
  }

  async getAllUsers(): Promise<User[]> {
    return db.select().from(schema.users).orderBy(desc(schema.users.createdAt));
  }

  // ─── Documents ────────────────────────────────────────────────────────────
  async createDocument(doc: InsertDocument): Promise<Document> {
    const result = await db.insert(schema.documents).values(doc).returning();
    return result[0];
  }

  async getDocument(id: string): Promise<Document | undefined> {
    const result = await db.select().from(schema.documents).where(eq(schema.documents.id, id)).limit(1);
    return result[0];
  }

  async getUserDocuments(userId: string): Promise<Document[]> {
    return db.select().from(schema.documents)
      .where(eq(schema.documents.userId, userId))
      .orderBy(desc(schema.documents.uploadDate));
  }

  async getAllDocuments(): Promise<Document[]> {
    return db.select().from(schema.documents).orderBy(desc(schema.documents.uploadDate));
  }

  async deleteDocument(id: string): Promise<void> {
    await db.delete(schema.documents).where(eq(schema.documents.id, id));
  }

  // ─── Document Chunks ──────────────────────────────────────────────────────
  async createDocumentChunks(chunks: InsertDocumentChunk[]): Promise<DocumentChunk[]> {
    if (chunks.length === 0) return [];
    const result = await db.insert(schema.documentChunks).values(chunks).returning();
    return result;
  }

  async getChunksByDocument(documentId: string): Promise<DocumentChunk[]> {
    return db.select().from(schema.documentChunks)
      .where(eq(schema.documentChunks.documentId, documentId))
      .orderBy(schema.documentChunks.chunkIndex);
  }

  async getChunksByUser(userId: string): Promise<DocumentChunk[]> {
    return db.select().from(schema.documentChunks)
      .where(eq(schema.documentChunks.userId, userId))
      .orderBy(schema.documentChunks.chunkIndex);
  }

  async deleteChunksByDocument(documentId: string): Promise<void> {
    await db.delete(schema.documentChunks).where(eq(schema.documentChunks.documentId, documentId));
  }

  // ─── Images ───────────────────────────────────────────────────────────────
  async createImage(img: InsertImage): Promise<Image> {
    const result = await db.insert(schema.images).values(img).returning();
    return result[0];
  }

  async getImage(id: string): Promise<Image | undefined> {
    const result = await db.select().from(schema.images).where(eq(schema.images.id, id)).limit(1);
    return result[0];
  }

  async getUserImages(userId: string): Promise<Image[]> {
    return db.select().from(schema.images)
      .where(eq(schema.images.userId, userId))
      .orderBy(desc(schema.images.uploadDate));
  }

  async getAllImages(): Promise<Image[]> {
    return db.select().from(schema.images).orderBy(desc(schema.images.uploadDate));
  }

  async deleteImage(id: string): Promise<void> {
    await db.delete(schema.images).where(eq(schema.images.id, id));
  }

  // ─── Chat Sessions ────────────────────────────────────────────────────────
  async createChatSession(session: InsertChatSession): Promise<ChatSession> {
    const result = await db.insert(schema.chatSessions).values(session).returning();
    return result[0];
  }

  async getChatSession(id: string): Promise<ChatSession | undefined> {
    const result = await db.select().from(schema.chatSessions).where(eq(schema.chatSessions.id, id)).limit(1);
    return result[0];
  }

  async getUserChatSessions(userId: string): Promise<ChatSession[]> {
    return db.select().from(schema.chatSessions)
      .where(eq(schema.chatSessions.userId, userId))
      .orderBy(desc(schema.chatSessions.updatedAt));
  }

  async updateChatSession(id: string, updates: Partial<InsertChatSession>): Promise<ChatSession | undefined> {
    const result = await db.update(schema.chatSessions)
      .set({ ...updates, updatedAt: new Date() })
      .where(eq(schema.chatSessions.id, id))
      .returning();
    return result[0];
  }

  async deleteChatSession(id: string): Promise<void> {
    await db.delete(schema.chatSessions).where(eq(schema.chatSessions.id, id));
  }

  // ─── Chat Messages ────────────────────────────────────────────────────────
  async createChatMessage(message: InsertChatMessage): Promise<ChatMessage> {
    const result = await db.insert(schema.chatMessages).values(message).returning();
    return result[0];
  }

  async getMessagesBySession(sessionId: string): Promise<ChatMessage[]> {
    return db.select().from(schema.chatMessages)
      .where(eq(schema.chatMessages.sessionId, sessionId))
      .orderBy(schema.chatMessages.createdAt);
  }

  async deleteMessagesBySession(sessionId: string): Promise<void> {
    await db.delete(schema.chatMessages).where(eq(schema.chatMessages.sessionId, sessionId));
  }

  // ─── Search History ───────────────────────────────────────────────────────
  async createSearchHistory(history: InsertSearchHistory): Promise<SearchHistory> {
    const result = await db.insert(schema.searchHistory).values(history).returning();
    return result[0];
  }

  async getUserSearchHistory(userId: string): Promise<SearchHistory[]> {
    return db.select().from(schema.searchHistory)
      .where(eq(schema.searchHistory.userId, userId))
      .orderBy(desc(schema.searchHistory.createdAt));
  }

  async getAllSearchHistory(): Promise<SearchHistory[]> {
    return db.select().from(schema.searchHistory).orderBy(desc(schema.searchHistory.createdAt));
  }

  async deleteSearchHistory(id: string): Promise<void> {
    await db.delete(schema.searchHistory).where(eq(schema.searchHistory.id, id));
  }

  // ─── API Settings ─────────────────────────────────────────────────────────
  async createApiSetting(setting: InsertApiSetting): Promise<ApiSetting> {
    const result = await db.insert(schema.apiSettings).values(setting).returning();
    return result[0];
  }

  async getApiSetting(keyName: string): Promise<ApiSetting | undefined> {
    const result = await db.select().from(schema.apiSettings)
      .where(eq(schema.apiSettings.keyName, keyName)).limit(1);
    return result[0];
  }

  async getAllApiSettings(): Promise<ApiSetting[]> {
    return db.select().from(schema.apiSettings);
  }

  async updateApiSetting(keyName: string, updates: Partial<InsertApiSetting>): Promise<ApiSetting | undefined> {
    const result = await db.update(schema.apiSettings)
      .set({ ...updates, updatedAt: new Date() })
      .where(eq(schema.apiSettings.keyName, keyName))
      .returning();
    return result[0];
  }

  // ─── Admin Logs ───────────────────────────────────────────────────────────
  async createAdminLog(log: InsertAdminLog): Promise<AdminLog> {
    const result = await db.insert(schema.adminLogs).values(log).returning();
    return result[0];
  }

  async getAllAdminLogs(): Promise<AdminLog[]> {
    return db.select().from(schema.adminLogs).orderBy(desc(schema.adminLogs.createdAt));
  }

  // ─── Notifications ────────────────────────────────────────────────────────
  async createNotification(notification: InsertNotification): Promise<Notification> {
    const result = await db.insert(schema.notifications).values(notification).returning();
    return result[0];
  }

  async getAllNotifications(): Promise<Notification[]> {
    return db.select().from(schema.notifications).orderBy(desc(schema.notifications.createdAt));
  }

  async markNotificationAsRead(id: string): Promise<void> {
    await db.update(schema.notifications).set({ isRead: true }).where(eq(schema.notifications.id, id));
  }

  async deleteNotification(id: string): Promise<void> {
    await db.delete(schema.notifications).where(eq(schema.notifications.id, id));
  }

  async clearAllNotifications(): Promise<void> {
    await db.delete(schema.notifications);
  }

  // ─── Dashboard Stats ──────────────────────────────────────────────────────
  async getDashboardStats() {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const [users, allHistory] = await Promise.all([
      db.select().from(schema.users),
      db.select().from(schema.searchHistory),
    ]);

    const todayHistory = allHistory.filter((h) => h.createdAt >= today);
    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
    const recentHistory = allHistory.filter((h) => h.createdAt >= oneHourAgo);
    const activeSessions = new Set(recentHistory.map((h) => h.userId)).size;

    return {
      totalUsers: users.length,
      queriesToday: todayHistory.length,
      apiQueries: allHistory.filter((h) => h.sourceType?.includes("API")).length,
      pdfQueries: allHistory.filter((h) => h.sourceType?.includes("PDF")).length,
      imageQueries: allHistory.filter((h) => h.sourceType?.includes("Image")).length,
      activeSessions,
    };
  }

  async getQueryAnalytics(): Promise<Array<{ name: string; queries: number; api: number }>> {
    const dayNames = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    const analytics = [];

    for (let i = 6; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      date.setHours(0, 0, 0, 0);

      const nextDate = new Date(date);
      nextDate.setDate(nextDate.getDate() + 1);

      const dayHistory = await db.select().from(schema.searchHistory)
        .where(sql`${schema.searchHistory.createdAt} >= ${date} AND ${schema.searchHistory.createdAt} < ${nextDate}`);

      analytics.push({
        name: dayNames[date.getDay()],
        queries: dayHistory.length,
        api: dayHistory.filter((h) => h.sourceType?.includes("API")).length,
      });
    }

    return analytics;
  }
}

export const storage = new DbStorage();

import type { Express, Request } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { generateToken, comparePassword, authMiddleware, adminMiddleware } from "./utils/auth";
import { upload, extractPdfText, deleteFile, chunkText, ensureUploadsDir } from "./utils/file-processor";
import {
  extractQueryIntent,
  classifyDomain,
  searchInDocuments,
  searchInChunks,
  analyzeImage,
  generateAgricultureResponse,
  lastUsedProvider,
} from "./utils/openai-service";
import { fetchAgricultureData } from "./utils/external-apis";
import { toHttpError } from "./utils/errors";
import { insertUserSchema, insertSearchHistorySchema, insertApiSettingSchema } from "@shared/schema";
import path from "path";
import fs from "fs/promises";

interface MulterRequest extends Request {
  file?: Express.Multer.File;
}

export async function registerRoutes(app: Express): Promise<Server> {

  await ensureUploadsDir();

  // ─── Auth ─────────────────────────────────────────────────────────────────
  app.post("/api/auth/signup", async (req, res) => {
    try {
      const userData = insertUserSchema.parse(req.body);
      const existingUser = await storage.getUserByEmail(userData.email);
      if (existingUser) return res.status(400).json({ message: "Email already registered" });

      const user = await storage.createUser(userData);
      const token = generateToken({ userId: user.id, email: user.email, role: user.role });
      res.json({ token, user: { id: user.id, email: user.email, fullName: user.fullName, role: user.role } });
    } catch (error: any) {
      res.status(400).json({ message: error.message || "Signup failed" });
    }
  });

  app.post("/api/auth/login", async (req, res) => {
    try {
      const { email, password } = req.body;
      const user = await storage.getUserByEmail(email);
      if (!user) return res.status(401).json({ message: "Invalid credentials" });
      if (!user.isActive) return res.status(403).json({ message: "Account is deactivated" });

      const isValid = await comparePassword(password, user.password);
      if (!isValid) return res.status(401).json({ message: "Invalid credentials" });

      const token = generateToken({ userId: user.id, email: user.email, role: user.role });
      res.json({ token, user: { id: user.id, email: user.email, fullName: user.fullName, role: user.role } });
    } catch (error: any) {
      res.status(500).json({ message: error.message || "Login failed" });
    }
  });

  // ─── User Profile ─────────────────────────────────────────────────────────
  app.get("/api/user/profile", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const user = await storage.getUser(userId);
      if (!user) return res.status(404).json({ message: "User not found" });
      res.json({ id: user.id, email: user.email, fullName: user.fullName, role: user.role, createdAt: user.createdAt });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.put("/api/user/profile", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const { fullName, password } = req.body;
      const updates: any = {};
      if (fullName) updates.fullName = fullName;
      if (password) updates.password = password;
      const user = await storage.updateUser(userId, updates);
      res.json({ message: "Profile updated successfully", user });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─── Chat Sessions ────────────────────────────────────────────────────────
  app.post("/api/chat/sessions", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const { title } = req.body;
      const session = await storage.createChatSession({ userId, title: title || "New Chat" });
      res.json(session);
    } catch (error: any) {
      const err = toHttpError(error);
      res.status(err.statusCode).json({ message: err.message, code: err.code });
    }
  });

  app.get("/api/chat/sessions", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const sessions = await storage.getUserChatSessions(userId);
      res.json(sessions);
    } catch (error: any) {
      const err = toHttpError(error);
      res.status(err.statusCode).json({ message: err.message, code: err.code });
    }
  });

  app.get("/api/chat/sessions/:id", authMiddleware, async (req, res) => {
    try {
      const session = await storage.getChatSession(req.params.id);
      if (!session) return res.status(404).json({ message: "Session not found" });
      const messages = await storage.getMessagesBySession(req.params.id);
      res.json({ session, messages });
    } catch (error: any) {
      const err = toHttpError(error);
      res.status(err.statusCode).json({ message: err.message, code: err.code });
    }
  });

  app.delete("/api/chat/sessions/:id", authMiddleware, async (req, res) => {
    try {
      await storage.deleteChatSession(req.params.id);
      res.json({ message: "Session deleted" });
    } catch (error: any) {
      const err = toHttpError(error);
      res.status(err.statusCode).json({ message: err.message, code: err.code });
    }
  });

  // ─── Search ───────────────────────────────────────────────────────────────
  app.post("/api/search/query", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const { query, sessionId } = req.body;
      const startTime = Date.now();

      // Step 1: Intent + domain in parallel
      const [extractedParams, domain] = await Promise.all([
        extractQueryIntent(query),
        classifyDomain(query),
      ]);

      if (domain !== "agriculture") {
        return res.status(400).json({
          message: "Currently only agriculture domain queries are supported",
          code: "DOMAIN_NOT_SUPPORTED",
        });
      }

      // Step 2: Fetch data sources in parallel
      const [apiResults, userDocuments, userImages, userChunks] = await Promise.all([
        fetchAgricultureData(extractedParams),
        storage.getUserDocuments(userId),
        storage.getUserImages(userId),
        storage.getChunksByUser(userId),
      ]);

      // Step 3: Search docs — prefer chunks if available, fallback to raw text
      let pdfResults: string[] = [];
      if (userChunks.length > 0) {
        pdfResults = await searchInChunks(query, userChunks);
      } else if (userDocuments.length > 0) {
        pdfResults = await searchInDocuments(query, userDocuments);
      }

      // Step 4: Image context
      const imageResults: string[] = [];
      for (const image of userImages.slice(0, 3)) {
        if (image.extractedData) imageResults.push(image.extractedData);
      }

      // Step 5: Generate answer
      const answer = await generateAgricultureResponse(
        query,
        extractedParams,
        apiResults.map((r) => r.data),
        pdfResults,
        imageResults
      );

      const aiProvider = lastUsedProvider;
      const executionTime = Date.now() - startTime;

      let sourceType = "";
      if (apiResults.length > 0) sourceType += "API";
      if (pdfResults.length > 0) sourceType += (sourceType ? "+PDF" : "PDF");
      if (imageResults.length > 0) sourceType += (sourceType ? "+Image" : "Image");
      if (!sourceType) sourceType = "None";

      // Step 6: Persist to search_history
      await storage.createSearchHistory(
        insertSearchHistorySchema.parse({
          userId,
          query,
          extractedParams,
          sourceType,
          results: { answer, apiResults, pdfResults, imageResults },
          agentUsed: `Agriculture/${aiProvider}`,
          executionTime,
        })
      );

      // Step 7: Persist to chat session if provided
      let activeSessionId = sessionId;
      if (activeSessionId) {
        await Promise.all([
          storage.createChatMessage({
            sessionId: activeSessionId,
            role: "user",
            content: query,
            metadata: null,
          }),
          storage.createChatMessage({
            sessionId: activeSessionId,
            role: "assistant",
            content: answer,
            metadata: { apiResults, pdfResults, imageResults, executionTime, aiProvider, sourceType },
          }),
        ]);

        // Update session title on first message
        const messages = await storage.getMessagesBySession(activeSessionId);
        if (messages.length <= 2) {
          const title = query.length > 50 ? query.substring(0, 50) + "..." : query;
          await storage.updateChatSession(activeSessionId, { title });
        }
      }

      res.json({
        answer,
        sourceType,
        extractedParams,
        apiResults: apiResults.map((r) => ({ source: r.source, data: r.data })),
        pdfResults,
        imageResults,
        executionTime,
        aiProvider,
        sessionId: activeSessionId,
      });
    } catch (error: any) {
      console.error("[search] Error:", error);
      const err = toHttpError(error);
      res.status(err.statusCode).json({ message: err.message, code: err.code });
    }
  });

  app.get("/api/search/history", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const history = await storage.getUserSearchHistory(userId);
      res.json(history);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/search/history/:id", authMiddleware, async (req, res) => {
    try {
      await storage.deleteSearchHistory(req.params.id);
      res.json({ message: "History entry deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─── Documents ────────────────────────────────────────────────────────────
  app.post("/api/documents/upload", authMiddleware, upload.single("file"), async (req: MulterRequest, res) => {
    try {
      if (!req.file) return res.status(400).json({ message: "No file uploaded" });

      const userId = (req as any).user.userId;
      const extractedText = await extractPdfText(req.file.path);

      const document = await storage.createDocument({
        userId,
        filename: req.file.originalname,
        filePath: req.file.path,
        extractedText,
        fileSize: req.file.size,
      });

      // Chunk and store in background (don't block response)
      if (extractedText && extractedText.trim().length > 0) {
        const chunks = chunkText(extractedText, 500, 100);
        if (chunks.length > 0) {
          const chunkInserts = chunks.map((c) => ({
            documentId: document.id,
            userId,
            chunkIndex: c.index,
            content: c.content,
            embedding: null as string | null,
          }));
          storage.createDocumentChunks(chunkInserts).catch((err) => {
            console.error("[chunks] Failed to store chunks:", err.message);
          });
        }
      }

      res.json({ message: "Document uploaded successfully", document });
    } catch (error: any) {
      const err = toHttpError(error);
      res.status(err.statusCode).json({ message: err.message, code: err.code });
    }
  });

  app.get("/api/documents/list", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const documents = await storage.getUserDocuments(userId);
      res.json(documents);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/documents/:id", authMiddleware, async (req, res) => {
    try {
      const doc = await storage.getDocument(req.params.id);
      if (doc) {
        await Promise.all([
          deleteFile(doc.filePath),
          storage.deleteChunksByDocument(req.params.id),
        ]);
        await storage.deleteDocument(req.params.id);
      }
      res.json({ message: "Document deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─── Images ───────────────────────────────────────────────────────────────
  app.post("/api/images/upload", authMiddleware, upload.single("file"), async (req: MulterRequest, res) => {
    try {
      if (!req.file) return res.status(400).json({ message: "No file uploaded" });

      const userId = (req as any).user.userId;
      const imageBuffer = await fs.readFile(req.file.path);
      const base64Image = imageBuffer.toString("base64");
      const dataUrl = `data:${req.file.mimetype};base64,${base64Image}`;

      const extractedData = await analyzeImage(dataUrl);

      const image = await storage.createImage({
        userId,
        filename: req.file.originalname,
        filePath: req.file.path,
        extractedData,
        fileSize: req.file.size,
      });

      res.json({ message: "Image uploaded successfully", image });
    } catch (error: any) {
      const err = toHttpError(error);
      res.status(err.statusCode).json({ message: err.message, code: err.code });
    }
  });

  app.get("/api/images/list", authMiddleware, async (req, res) => {
    try {
      const userId = (req as any).user.userId;
      const images = await storage.getUserImages(userId);
      res.json(images);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/images/:id", authMiddleware, async (req, res) => {
    try {
      const img = await storage.getImage(req.params.id);
      if (img) {
        await deleteFile(img.filePath);
        await storage.deleteImage(req.params.id);
      }
      res.json({ message: "Image deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─── Admin ────────────────────────────────────────────────────────────────
  app.get("/api/admin/dashboard", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const stats = await storage.getDashboardStats();
      res.json(stats);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/analytics", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const analytics = await storage.getQueryAnalytics();
      res.json(analytics);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/users", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const users = await storage.getAllUsers();
      res.json(users.map((u) => ({
        id: u.id, email: u.email, fullName: u.fullName,
        role: u.role, isActive: u.isActive, createdAt: u.createdAt,
      })));
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/admin/users", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const userData = insertUserSchema.parse(req.body);
      const existing = await storage.getUserByEmail(userData.email);
      if (existing) return res.status(400).json({ message: "Email already exists" });
      const user = await storage.createUser(userData);
      await storage.createAdminLog({
        adminId: (req as any).user.userId,
        action: "create_user",
        targetEntity: "user",
        targetId: user.id,
        details: { email: user.email },
      });
      res.json({ message: "User created", user });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.put("/api/admin/users/:id", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const { isActive } = req.body;
      const user = await storage.updateUser(req.params.id, { isActive });
      await storage.createAdminLog({
        adminId: (req as any).user.userId,
        action: isActive ? "activate_user" : "deactivate_user",
        targetEntity: "user",
        targetId: req.params.id,
        details: { isActive },
      });
      res.json({ message: "User updated", user });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/admin/users/:id", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      await storage.deleteUser(req.params.id);
      await storage.createAdminLog({
        adminId: (req as any).user.userId,
        action: "delete_user",
        targetEntity: "user",
        targetId: req.params.id,
        details: {},
      });
      res.json({ message: "User deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/documents", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      res.json(await storage.getAllDocuments());
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/images", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      res.json(await storage.getAllImages());
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/logs", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      res.json(await storage.getAllAdminLogs());
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/search-history", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      res.json(await storage.getAllSearchHistory());
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/settings", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      res.json(await storage.getAllApiSettings());
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.put("/api/admin/settings", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      const { keyName, keyValue, isActive } = req.body;
      const existing = await storage.getApiSetting(keyName);
      let setting;
      if (existing) {
        setting = await storage.updateApiSetting(keyName, { keyValue, isActive });
      } else {
        setting = await storage.createApiSetting(insertApiSettingSchema.parse({ keyName, keyValue, isActive }));
      }
      await storage.createAdminLog({
        adminId: (req as any).user.userId,
        action: "update_setting",
        targetEntity: "api_setting",
        targetId: setting?.id,
        details: { keyName },
      });
      res.json({ message: "Setting updated", setting });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/admin/notifications", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      res.json(await storage.getAllNotifications());
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/admin/notifications/clear", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      await storage.clearAllNotifications();
      res.json({ message: "All notifications cleared" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.delete("/api/admin/notifications/:id", authMiddleware, adminMiddleware, async (req, res) => {
    try {
      await storage.deleteNotification(req.params.id);
      res.json({ message: "Notification deleted" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  const httpServer = createServer(app);
  return httpServer;
}

import { useState, useRef, useEffect, useCallback } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import { useToast } from "@/hooks/use-toast";
import { Send, Paperclip, FileText, Image, X, Loader2, RefreshCw, Zap, Bot } from "lucide-react";
import type { SearchHistory, ChatSession, ChatMessage } from "@shared/schema";

interface Message {
  id: string;
  type: "user" | "assistant" | "error";
  content: string;
  query?: string;
  results?: any;
  executionTime?: number;
  aiProvider?: string;
  attachments?: { type: "pdf" | "image"; name: string }[];
  timestamp: Date;
  failed?: boolean;
  retryQuery?: string;
}

const PROVIDER_COLORS: Record<string, string> = {
  gemini: "text-blue-400",
  openai: "text-emerald-400",
};

const PROVIDER_ICONS: Record<string, string> = {
  gemini: "✦",
  openai: "⚡",
};

export default function ChatPage() {
  const { toast } = useToast();
  const qc = useQueryClient();
  const [query, setQuery] = useState("");
  const [messages, setMessages] = useState<Message[]>([]);
  const [attachments, setAttachments] = useState<File[]>([]);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isUploading, setIsUploading] = useState(false);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [conversationContext, setConversationContext] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const initialized = useRef(false);

  // ─── Load or create chat session ──────────────────────────────────────────
  useEffect(() => {
    if (initialized.current) return;

    const handleNewChat = () => {
      setMessages([]);
      setQuery("");
      setAttachments([]);
      setConversationContext("");
      setSessionId(null);
      initialized.current = true;
      localStorage.removeItem("activeConversation");
      localStorage.removeItem("activeChatSessionId");
    };

    window.addEventListener("newChat", handleNewChat);
    return () => window.removeEventListener("newChat", handleNewChat);
  }, []);

  // Restore active conversation from history click
  useEffect(() => {
    if (initialized.current) return;

    const activeConversation = localStorage.getItem("activeConversation");
    if (activeConversation) {
      try {
        const data = JSON.parse(activeConversation);
        const results = data.results as any;
        setMessages([
          {
            id: `user-${data.id}`,
            type: "user",
            content: data.query,
            timestamp: new Date(data.createdAt),
          },
          {
            id: `assistant-${data.id}`,
            type: "assistant",
            content: results?.answer || "No response available",
            results,
            executionTime: data.executionTime,
            aiProvider: data.agentUsed?.split("/")?.[1],
            timestamp: new Date(data.createdAt),
          },
        ]);
        setConversationContext((data.query + " " + (results?.answer || "")).slice(0, 1000));
        localStorage.removeItem("activeConversation");
        initialized.current = true;
        return;
      } catch { /* ignore */ }
    }

    // Restore active session
    const savedSessionId = localStorage.getItem("activeChatSessionId");
    if (savedSessionId) {
      setSessionId(savedSessionId);
      apiRequest(`/api/chat/sessions/${savedSessionId}`)
        .then(({ messages: msgs }: { session: ChatSession; messages: ChatMessage[] }) => {
          const loaded: Message[] = msgs.map((m) => ({
            id: m.id,
            type: m.role as "user" | "assistant",
            content: m.content,
            results: (m.metadata as any)?.apiResults ? m.metadata : undefined,
            executionTime: (m.metadata as any)?.executionTime,
            aiProvider: (m.metadata as any)?.aiProvider,
            timestamp: new Date(m.createdAt),
          }));
          setMessages(loaded);
          if (msgs.length > 0) {
            const lastPair = msgs.slice(-2);
            setConversationContext(lastPair.map((m) => m.content).join(" ").slice(0, 1000));
          }
        })
        .catch(() => {
          localStorage.removeItem("activeChatSessionId");
        });
    }

    initialized.current = true;
  }, []);

  // Persist session ID
  useEffect(() => {
    if (sessionId) {
      localStorage.setItem("activeChatSessionId", sessionId);
    }
  }, [sessionId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // ─── Helpers ───────────────────────────────────────────────────────────────
  const ensureSession = useCallback(async (): Promise<string> => {
    if (sessionId) return sessionId;
    const session: ChatSession = await apiRequest("/api/chat/sessions", {
      method: "POST",
      body: JSON.stringify({ title: "New Chat" }),
    });
    setSessionId(session.id);
    qc.invalidateQueries({ queryKey: ["/api/chat/sessions"] });
    return session.id;
  }, [sessionId, qc]);

  const uploadFile = async (file: File, onProgress: (pct: number) => void): Promise<any> => {
    const formData = new FormData();
    formData.append("file", file);
    const isPDF = file.type === "application/pdf";
    const endpoint = isPDF ? "/api/documents/upload" : "/api/images/upload";
    const token = localStorage.getItem("token");

    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open("POST", endpoint);
      if (token) xhr.setRequestHeader("Authorization", `Bearer ${token}`);

      xhr.upload.onprogress = (e) => {
        if (e.lengthComputable) onProgress(Math.round((e.loaded / e.total) * 100));
      };

      xhr.onload = () => {
        if (xhr.status >= 200 && xhr.status < 300) {
          resolve(JSON.parse(xhr.responseText));
        } else {
          reject(new Error(`Upload failed: ${xhr.statusText}`));
        }
      };

      xhr.onerror = () => reject(new Error("Upload network error"));
      xhr.send(formData);
    });
  };

  // ─── Search mutation ───────────────────────────────────────────────────────
  const searchMutation = useMutation({
    mutationFn: async ({ searchQuery, sid }: { searchQuery: string; sid: string }) => {
      const fullQuery = conversationContext
        ? `Follow-up (context: ${conversationContext.slice(0, 300)}): ${searchQuery}`
        : searchQuery;
      return apiRequest("/api/search/query", {
        method: "POST",
        body: JSON.stringify({ query: fullQuery, sessionId: sid }),
      });
    },
    onSuccess: (data, { searchQuery }) => {
      qc.invalidateQueries({ queryKey: ["/api/search/history"] });
      qc.invalidateQueries({ queryKey: ["/api/chat/sessions"] });

      const assistantMessage: Message = {
        id: `assistant-${Date.now()}`,
        type: "assistant",
        content: data.answer || "I found some results for your query.",
        results: data,
        executionTime: data.executionTime,
        aiProvider: data.aiProvider,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, assistantMessage]);
      setConversationContext((prev) => (prev + " " + data.answer).slice(-1000));
    },
    onError: (error: any, { searchQuery }) => {
      const code = error.message?.includes("DOMAIN_NOT_SUPPORTED")
        ? "Only agriculture queries are supported right now."
        : error.message?.includes("TIMEOUT")
        ? "The request timed out. Please try again."
        : error.message || "Search failed. Please try again.";

      const errorMessage: Message = {
        id: `error-${Date.now()}`,
        type: "error",
        content: code,
        failed: true,
        retryQuery: searchQuery,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, errorMessage]);

      toast({ title: "Search Failed", description: code, variant: "destructive" });
    },
  });

  const handleSubmit = async (e: React.FormEvent, retryQuery?: string) => {
    e?.preventDefault();
    const finalQuery = retryQuery || query;
    if (!finalQuery.trim() && attachments.length === 0) return;

    const uploadedAttachments: { type: "pdf" | "image"; name: string }[] = [];

    if (attachments.length > 0) {
      setIsUploading(true);
      setUploadProgress(0);
      try {
        for (let i = 0; i < attachments.length; i++) {
          const file = attachments[i];
          await uploadFile(file, (pct) => {
            setUploadProgress(Math.round(((i + pct / 100) / attachments.length) * 100));
          });
          uploadedAttachments.push({
            type: file.type === "application/pdf" ? "pdf" : "image",
            name: file.name,
          });
        }
        setUploadProgress(100);
        qc.invalidateQueries({ queryKey: ["/api/documents/list"] });
        qc.invalidateQueries({ queryKey: ["/api/images/list"] });
      } catch {
        toast({ title: "Upload Failed", description: "Failed to upload attachments", variant: "destructive" });
        setIsUploading(false);
        setUploadProgress(0);
        return;
      }
      setIsUploading(false);
      setUploadProgress(0);
    }

    const userMessage: Message = {
      id: `user-${Date.now()}`,
      type: "user",
      content: finalQuery || "Analyze uploaded files",
      attachments: uploadedAttachments.length > 0 ? uploadedAttachments : undefined,
      timestamp: new Date(),
    };

    setMessages((prev) => [...prev, userMessage]);
    if (!retryQuery) {
      setQuery("");
      setAttachments([]);
    }

    if (finalQuery.trim()) {
      const sid = await ensureSession();
      searchMutation.mutate({ searchQuery: finalQuery, sid });
    } else if (uploadedAttachments.length > 0) {
      setMessages((prev) => [
        ...prev,
        {
          id: `assistant-${Date.now()}`,
          type: "assistant",
          content: `${uploadedAttachments.length} file(s) uploaded and chunked for search. Ask me anything about them.`,
          timestamp: new Date(),
        },
      ]);
    }
  };

  const handleRetry = (retryQuery: string) => {
    setMessages((prev) => prev.filter((m) => m.type !== "error" || m.retryQuery !== retryQuery));
    handleSubmit(null as any, retryQuery);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []).filter(
      (f) => f.type === "application/pdf" || f.type.startsWith("image/")
    );
    setAttachments((prev) => [...prev, ...files]);
    e.target.value = "";
  };

  const formatApiResults = (results: any) => {
    if (!results) return null;

    const apiResults = results.apiResults || [];
    const pdfResults = results.pdfResults || [];
    const imageResults = results.imageResults || [];
    const priceData = apiResults.find((api: any) => api.data?.currentPrice);

    if (!priceData?.data?.currentPrice && pdfResults.length === 0 && imageResults.length === 0) return null;

    return (
      <div className="mt-4 space-y-3">
        {priceData?.data?.currentPrice && (
          <div className="bg-emerald-50 dark:bg-emerald-900/20 rounded-lg p-4">
            <div className="flex items-center gap-2 mb-3">
              <span className="text-lg">🌾</span>
              <span className="font-semibold text-emerald-700 dark:text-emerald-400 text-sm">Market Data</span>
              <span className="text-xs text-gray-400 ml-auto">HDX HAPI</span>
            </div>
            <div className="grid grid-cols-2 gap-3 text-sm">
              {priceData.data.crop && (
                <div>
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Commodity</p>
                  <p className="font-medium text-gray-800 dark:text-gray-200">{priceData.data.crop}</p>
                </div>
              )}
              {priceData.data.country && (
                <div>
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Location</p>
                  <p className="font-medium text-gray-800 dark:text-gray-200">{priceData.data.country}</p>
                </div>
              )}
              {priceData.data.currentPrice && (
                <div>
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Current Price</p>
                  <p className="font-medium text-emerald-600 dark:text-emerald-400">
                    {priceData.data.currency} {priceData.data.currentPrice.toLocaleString()}/{priceData.data.unit}
                  </p>
                </div>
              )}
              {priceData.data.averagePrice && (
                <div>
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Average Price</p>
                  <p className="font-medium text-gray-800 dark:text-gray-200">
                    {priceData.data.currency} {priceData.data.averagePrice.toLocaleString()}/{priceData.data.unit}
                  </p>
                </div>
              )}
              {priceData.data.lastUpdated && (
                <div className="col-span-2">
                  <p className="text-gray-500 dark:text-gray-400 text-xs">Last Updated</p>
                  <p className="font-medium text-gray-800 dark:text-gray-200">
                    {new Date(priceData.data.lastUpdated).toLocaleDateString()}
                  </p>
                </div>
              )}
            </div>
          </div>
        )}

        {pdfResults.length > 0 && (
          <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-3 flex items-center gap-2">
            <FileText className="w-4 h-4 text-blue-500 flex-shrink-0" />
            <span className="text-sm text-blue-700 dark:text-blue-400">
              Retrieved from {pdfResults.length} document chunk(s)
            </span>
          </div>
        )}

        {imageResults.length > 0 && (
          <div className="bg-purple-50 dark:bg-purple-900/20 rounded-lg p-3 flex items-center gap-2">
            <Image className="w-4 h-4 text-purple-500 flex-shrink-0" />
            <span className="text-sm text-purple-700 dark:text-purple-400">
              Analyzed {imageResults.length} image(s)
            </span>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-[calc(100vh-120px)] md:h-[calc(100vh-80px)] max-w-4xl mx-auto pb-16 md:pb-0">
      {/* Messages */}
      <div className="flex-1 overflow-y-auto scrollbar-hide px-2 md:px-4 py-4 md:py-6 space-y-4 md:space-y-6">
        {messages.length === 0 && (
          <div className="text-center py-16 space-y-6">
            <h1 className="text-3xl font-bold text-white" data-testid="heading-chat">
              What would you like to know?
            </h1>
            <p className="text-gray-400 max-w-lg mx-auto">
              Ask anything about agriculture, climate, or market data. Attach PDFs and images for deeper analysis.
            </p>
            <div className="flex flex-wrap gap-3 justify-center mt-8">
              {["Maize prices in Kenya", "Food security Ethiopia", "Wheat market trends"].map((s) => (
                <button
                  key={s}
                  onClick={() => setQuery(s)}
                  className="px-4 py-2 bg-[#2a3749] hover:bg-[#3a4759] text-gray-300 rounded-full text-sm transition-colors"
                  data-testid={`button-suggestion-${s}`}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        )}

        {messages.map((message) => (
          <div
            key={message.id}
            className={`flex ${message.type === "user" ? "justify-end" : "justify-start"}`}
          >
            {message.type === "error" ? (
              <div className="max-w-[85%] rounded-2xl px-5 py-4 bg-red-900/30 border border-red-700/50 text-white">
                <p className="text-red-300 text-sm">{message.content}</p>
                {message.retryQuery && (
                  <button
                    onClick={() => handleRetry(message.retryQuery!)}
                    className="flex items-center gap-2 mt-3 text-xs text-red-400 hover:text-white transition-colors"
                    data-testid="button-retry"
                  >
                    <RefreshCw className="w-3 h-3" />
                    Retry
                  </button>
                )}
              </div>
            ) : (
              <div
                className={`max-w-[85%] rounded-2xl px-5 py-4 ${
                  message.type === "user"
                    ? "bg-emerald-500 text-white"
                    : "bg-[#2a3749] text-white"
                }`}
                data-testid={`message-${message.type}-${message.id}`}
              >
                {/* Attachments */}
                {message.attachments && message.attachments.length > 0 && (
                  <div className="flex flex-wrap gap-2 mb-2">
                    {message.attachments.map((att, idx) => (
                      <div
                        key={idx}
                        className="flex items-center gap-1 bg-white/20 rounded px-2 py-1 text-xs"
                      >
                        {att.type === "pdf" ? <FileText className="w-3 h-3" /> : <Image className="w-3 h-3" />}
                        {att.name}
                      </div>
                    ))}
                  </div>
                )}

                <p className="whitespace-pre-wrap leading-relaxed text-sm md:text-base">{message.content}</p>

                {message.type === "assistant" && message.results && formatApiResults(message.results)}

                {/* Footer: time + AI provider */}
                {message.type === "assistant" && (
                  <div className="flex items-center gap-3 mt-3 pt-2 border-t border-white/10">
                    {message.executionTime && (
                      <span className="text-xs text-gray-400">
                        {(message.executionTime / 1000).toFixed(1)}s
                      </span>
                    )}
                    {message.aiProvider && (
                      <span
                        className={`text-xs flex items-center gap-1 ${PROVIDER_COLORS[message.aiProvider] || "text-gray-400"}`}
                        data-testid="text-ai-provider"
                      >
                        <span>{PROVIDER_ICONS[message.aiProvider] || "○"}</span>
                        {message.aiProvider === "gemini" ? "Gemini 1.5 Flash" : "GPT-4o"}
                      </span>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        ))}

        {searchMutation.isPending && (
          <div className="flex justify-start">
            <div className="bg-[#2a3749] rounded-2xl px-5 py-4 flex items-center gap-3">
              <Loader2 className="w-5 h-5 animate-spin text-emerald-400" />
              <span className="text-gray-300 text-sm">Searching agriculture data...</span>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input area */}
      <div className="border-t border-[#3a4759] bg-[#1e293b] p-4">
        {/* Upload progress */}
        {isUploading && (
          <div className="mb-3">
            <div className="flex items-center justify-between mb-1">
              <span className="text-xs text-gray-400">Uploading files...</span>
              <span className="text-xs text-gray-400">{uploadProgress}%</span>
            </div>
            <Progress value={uploadProgress} className="h-1.5" />
          </div>
        )}

        {/* Attachments preview */}
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-2 mb-3">
            {attachments.map((file, idx) => (
              <div
                key={idx}
                className="flex items-center gap-2 bg-[#2a3749] rounded-lg px-3 py-2 text-sm text-white"
              >
                {file.type === "application/pdf" ? (
                  <FileText className="w-4 h-4 text-blue-400" />
                ) : (
                  <Image className="w-4 h-4 text-purple-400" />
                )}
                <span className="max-w-[140px] truncate text-xs">{file.name}</span>
                <button
                  onClick={() => setAttachments((prev) => prev.filter((_, i) => i !== idx))}
                  className="hover:text-red-400 transition-colors"
                  data-testid={`button-remove-attachment-${idx}`}
                >
                  <X className="w-3 h-3" />
                </button>
              </div>
            ))}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex items-center gap-3">
          <input
            ref={fileInputRef}
            type="file"
            accept=".pdf,image/*"
            multiple
            onChange={handleFileSelect}
            className="hidden"
            data-testid="input-file-upload"
          />

          <Button
            type="button"
            variant="ghost"
            size="icon"
            onClick={() => fileInputRef.current?.click()}
            className="text-gray-400 hover:text-white hover:bg-[#2a3749] flex-shrink-0"
            disabled={isUploading}
            data-testid="button-attach-file"
          >
            <Paperclip className="w-5 h-5" />
          </Button>

          <Input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                handleSubmit(e as any);
              }
            }}
            placeholder="Ask about agriculture data, or attach a PDF/image..."
            className="flex-1 bg-[#2a3749] border-[#3a4759] text-white h-12 placeholder:text-gray-500 text-sm"
            disabled={searchMutation.isPending || isUploading}
            data-testid="input-chat-query"
          />

          <Button
            type="submit"
            size="icon"
            className="bg-emerald-500 hover:bg-emerald-600 h-12 w-12 flex-shrink-0"
            disabled={searchMutation.isPending || isUploading || (!query.trim() && attachments.length === 0)}
            data-testid="button-send-message"
          >
            {searchMutation.isPending ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <Send className="w-5 h-5" />
            )}
          </Button>
        </form>
      </div>
    </div>
  );
}

